// Copies the repo docs into the Starlight content folder and adds frontmatter.
// Runs before every dev/build so the site never drifts from the repo.
// Generated files are gitignored (see site/.gitignore).
import { copyFileSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '../..');
const out = resolve(here, '../src/content/docs');
const GH = 'https://github.com/adar2378/claude-garage/blob/main/';
const GEN = '<!-- GENERATED by site/scripts/sync-docs.mjs. Do not edit; edit the source in the repo. -->\n\n';

const yaml = (s) => JSON.stringify(s);

function descriptionOf(body, fallback) {
  const para = body
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .find((p) => p && !/^(#|\||```|<|[-*] |\d+\. |>)/.test(p));
  if (!para) return fallback;
  let t = para
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[`*_]/g, '')
    .replace(/\s+/g, ' ');
  if (t.length > 158) t = t.slice(0, 157).replace(/\s+\S*$/, '') + '.';
  return t;
}

function rewriteLinks(body, fromDir) {
  return body.replace(/\]\(([^)\s]+)\)/g, (m, href) => {
    if (/^(https?:|mailto:|#|\/)/.test(href)) return m;
    const [pathPart, hash = ''] = href.split(/(?=#)/);
    if (fromDir === 'plugins' && /^[\w-]+\.md$/.test(pathPart)) {
      const name = pathPart.replace(/\.md$/, '');
      const slug = name === 'README' ? '' : `${name}/`;
      return `](/docs/plugins/${slug}${hash})`;
    }
    // Anything else points at a repo file: send it to GitHub.
    const rel = join(fromDir === 'plugins' ? 'docs/plugins' : fromDir === 'docs' ? 'docs' : '', pathPart);
    return `](${GH}${rel.replace(/\\/g, '/')}${hash})`;
  });
}

function page({ title, description, order, body, extra = '' }) {
  const fm = ['---', `title: ${yaml(title)}`, `description: ${yaml(description)}`];
  if (order !== undefined) fm.push('sidebar:', `  order: ${order}`);
  if (extra) fm.push(extra);
  fm.push('---', '');
  return fm.join('\n') + '\n' + GEN + body.trim() + '\n';
}

function write(rel, content) {
  const file = join(out, rel);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
}

function splitTitle(md, fallback) {
  const m = md.match(/^#\s+(.+)\n/);
  return m ? { title: m[1].trim(), body: md.slice(m[0].length) } : { title: fallback, body: md };
}

// 1. Plugins
const pluginsSrc = join(repo, 'docs/plugins');
rmSync(join(out, 'plugins'), { recursive: true, force: true });
const order = ['README', 'quick-start', 'manifest', 'widgets', 'panes', 'actions', 'events', 'cli', 'api', 'permissions', 'storage', 'security', 'versioning'];
for (const f of readdirSync(pluginsSrc).filter((f) => f.endsWith('.md'))) {
  const name = f.replace(/\.md$/, '');
  const { title, body } = splitTitle(readFileSync(join(pluginsSrc, f), 'utf8'), name);
  const idx = order.indexOf(name);
  write(
    name === 'README' ? 'plugins/index.md' : `plugins/${f}`,
    page({
      title: name === 'README' ? 'Plugins' : title,
      description: descriptionOf(body, `${title}: claude-garage plugin reference.`),
      order: idx < 0 ? 99 : idx,
      body: rewriteLinks(body, 'plugins'),
    }),
  );
}

// 2. Platforms
{
  const { body } = splitTitle(readFileSync(join(repo, 'docs/PLATFORMS.md'), 'utf8'), 'Platforms');
  write(
    'platforms.md',
    page({
      title: 'Platforms',
      description: 'Which operating systems claude-garage supports, and how sessions run on each.',
      body: rewriteLinks(body, 'docs'),
    }),
  );
}

// 3. Changelog
{
  const { body } = splitTitle(readFileSync(join(repo, 'CHANGELOG.md'), 'utf8'), 'Changelog');
  write(
    'changelog.md',
    page({
      title: 'Changelog',
      description: 'Release notes for every claude-garage version.',
      body: rewriteLinks(body, ''),
      extra: 'tableOfContents: false',
    }),
  );
}

// 4. Key reference, generated from wall/src/ui/help.rs BINDINGS
{
  const src = readFileSync(join(repo, 'wall/src/ui/help.rs'), 'utf8');
  const block = src.match(/pub const BINDINGS[^=]*=\s*\[([\s\S]*?)\n\];/);
  if (!block) throw new Error('sync-docs: BINDINGS not found in wall/src/ui/help.rs');
  const rows = [...block[1].matchAll(/\(\s*"((?:[^"\\]|\\.)*)"\s*,\s*"((?:[^"\\]|\\.)*)"\s*,?\s*\)/g)].map((m) => [m[1], m[2]]);
  if (rows.length < 10) throw new Error(`sync-docs: parsed only ${rows.length} bindings`);
  const esc = (s) => s.replace(/\|/g, '\\|');
  const table = ['| Key | Action |', '|---|---|', ...rows.map(([k, v]) => `| \`${esc(k)}\` | ${esc(v)} |`)].join('\n');
  write(
    'reference/keys.md',
    page({
      title: 'Keys',
      description: 'Every key binding in the claude-garage wall. Press ? in the wall to see the same list.',
      order: 1,
      body: `This list is generated from the key legend in the wall (the \`?\` overlay), so it always matches the binary. Plugins can add more keys; they show up under a Plugins heading in the \`?\` overlay.\n\n${table}\n`,
    }),
  );
  console.log(`sync-docs: ${rows.length} key bindings`);
}
// 5. Brand renders: the landing page references /renders/*.svg. Copied, never committed twice (gitignored).
{
  const from = join(repo, 'docs/brand/renders');
  const to = resolve(here, '../public/renders');
  rmSync(to, { recursive: true, force: true });
  mkdirSync(to, { recursive: true });
  const files = readdirSync(from).filter((f) => f.endsWith('.svg'));
  for (const f of files) copyFileSync(join(from, f), join(to, f));
  console.log(`sync-docs: ${files.length} brand renders`);
}
console.log('sync-docs: done');
